window.QA_SQL_QUESTIONS = [
{"id":"sql-select","version":2,"title":"Какие данные вернёт этот запрос?","context":"В products хранятся названия (name), цены в шекелях (price) и количество товара на складе (stock). Выбери состав результата, а не порядок строк.","query":"SELECT name\nFROM products;","choices":["Названия, цены и остатки всех товаров.","Только названия всех товаров.","Только названия товаров, которые есть на складе."],"answer":1,"hint":"Посмотри на список после SELECT. Есть ли в запросе WHERE?","why":["Здесь выбран один столбец name. Для всех столбцов нужен SELECT *.","Верно: выбран только name, а ограничения строк через WHERE нет.","Условия stock > 0 в запросе нет. Отсутствующие на складе товары тоже останутся в результате."],"steps":["FROM products задаёт таблицу-источник.","SELECT name выбирает только столбец с названием.","WHERE отсутствует: запрос не отбирает товары по цене или наличию."],"rule":"SELECT — какие столбцы показать; WHERE — какие строки оставить. Без ORDER BY порядок строк не гарантируется.","columns":["name","price","stock"],"rows":[["iPhone 15",3000,5],["Samsung S24",2500,0],["Xiaomi 13",1500,10],["iPhone 14",2200,3]],"displayOrder":[1,0,2],"verification":{"sql":"SELECT name FROM products;","columns":["name"],"rows":[["iPhone 15"],["Samsung S24"],["Xiaomi 13"],["iPhone 14"]]},"source":"https://www.sqlite.org/lang_select.html"},
{"id":"sql-greater","version":2,"title":"Какое условие выберет товары строго дороже 2000 ₪?","context":"Нужен отбор по цене. Товар за ровно 2000 ₪ включать нельзя. Значения price — целые числа, NULL в этом задании нет.","query":"SELECT name, price\nFROM products\nWHERE /* выбери условие */;","choices":["price < 2000","price > 2000","price >= 2000"],"answer":1,"hint":"«Строго дороже» означает «больше», без равенства. Проверь знак на цене ровно 2000.","why":["Знак < выбирает цены меньше 2000 — это дешевле, а не дороже.","Верно: > выбирает цены больше 2000 и не включает саму границу.",">= включит и цену ровно 2000. В условии задачи её нужно исключить."],"steps":["Проверяем price, потому что требуется отбор по цене.","Строго больше записывается знаком >.","Цена 2000 не проходит; 2200 проходит."],"rule":"> — строго больше. >= — больше или равно. Различие проверяют на самой границе.","columns":["name","price","stock"],"rows":[["iPhone 15",3000,5],["Samsung S24",2500,0],["Xiaomi 13",1500,10],["iPhone 14",2200,3]],"displayOrder":[0,2,1],"verification":{"sql":"SELECT name,price FROM products WHERE price > 2000;","columns":["name","price"],"rows":[["iPhone 15",3000],["Samsung S24",2500],["iPhone 14",2200]]},"source":"https://www.sqlite.org/lang_select.html"},
{"id":"sql-boundary","version":2,"title":"Вернёт ли запрос показанный товар за 2500 ₪?","context":"В этом задании таблица products содержит только одну строку, показанную ниже. Цена — число; других условий отбора нет.","query":"SELECT name, price\nFROM products\nWHERE price < 2500;","choices":["Да: условие включает цену 2500.","Нет: цена 2500 не меньше 2500.","Запрос завершится ошибкой из-за равенства цены границе."],"answer":1,"hint":"< означает «меньше», а <= — «меньше или равно». Равенство само по себе не является ошибкой SQL.","why":["Строгое сравнение < не включает равенство. Для включения границы нужен <=.","Верно: 2500 равно 2500, но не меньше него.","Сравнение допустимо. Оно даёт отрицательный результат, а не ошибку выполнения."],"steps":["Берём цену из строки: 2500.","Проверяем: 2500 меньше 2500? Нет.","WHERE исключает эту строку. Результат пустой — это нормальная работа запроса."],"rule":"Пустой результат SELECT не означает ошибку. Он может означать, что подходящих строк нет.","columns":["name","price","stock"],"rows":[["Samsung S24",2500,0]],"displayOrder":[0,1,2],"verification":{"sql":"SELECT name,price FROM products WHERE price < 2500;","columns":["name","price"],"rows":[]},"source":"https://www.sqlite.org/lang_select.html"},
{"id":"sql-and","version":2,"title":"Попадёт ли этот товар в результат запроса?","context":"Нужно выбрать товары дешевле 2500 ₪, которые есть на складе. В этом задании products содержит одну строку: цена 2200 ₪, остаток 0 штук. stock — количество единиц товара, а не его цена.","query":"SELECT name, price, stock\nFROM products\nWHERE price < 2500\n  AND stock > 0;","choices":["Да: цена меньше 2500, этого достаточно.","Нет: товар отсутствует на складе.","Нет: запрос требует цену больше 2500."],"answer":1,"hint":"Проверь условия отдельно: подходит ли цена? Есть ли хотя бы одна единица? AND требует оба ответа «да».","why":["Ты верно проверил цену, но пропустил наличие. При AND одной подходящей цены недостаточно.","Верно: цена подходит, но остаток равен нулю. Второе условие не выполнено.","В запросе price < 2500, то есть меньше, не больше. Причина исключения — нулевой остаток, а не цена."],"steps":["Цена меньше 2500? Да: 2200 меньше 2500.","На складе больше нуля единиц? Нет: остаток 0, товара нет.","AND означает «И»: нужны оба условия одновременно. Одно не выполнено — строка не попадает в результат."],"rule":"Для AND должны выполняться оба условия. Пустой результат здесь правильный. При том же price и stock = 1 товар уже подошёл бы.","columns":["name","price","stock"],"rows":[["Учебный телефон",2200,0]],"displayOrder":[1,2,0],"verification":{"sql":"SELECT name,price,stock FROM products WHERE price < 2500 AND stock > 0;","columns":["name","price","stock"],"rows":[]},"source":"https://www.sqlite.org/lang_select.html"},
{"id":"sql-fields","version":2,"title":"Какой запрос вернёт ровно два столбца: name и price?","context":"Нужны названия и цены всех товаров, без отбора по наличию. Выбери запрос, а не отдельный фрагмент. Порядок строк не задан.","query":"","choices":["SELECT name AND price FROM products;","SELECT * FROM products;","SELECT name, price FROM products;"],"answer":2,"hint":"В списке SELECT столбцы разделяются запятой. * выбирает все столбцы.","why":["AND — логический оператор, а не разделитель столбцов. В SQLite такой запрос вычислит одно выражение, а не вернёт две колонки.","В таблице три столбца. * вернёт также stock, которого не должно быть в результате этой задачи.","Верно: name и price разделены запятой; stock не выбран."],"steps":["После SELECT перечисляем требуемые столбцы через запятую.","FROM products указывает исходную таблицу.","WHERE не нужен: в задаче нет ограничения строк."],"rule":"Запятая перечисляет выходные столбцы. AND соединяет логические условия; это разные задачи.","columns":["name","price","stock"],"rows":[["iPhone 15",3000,5],["Samsung S24",2500,0],["Xiaomi 13",1500,10],["iPhone 14",2200,3]],"displayOrder":[2,0,1],"verification":{"sql":"SELECT name,price FROM products;","columns":["name","price"],"rows":[["iPhone 15",3000],["Samsung S24",2500],["Xiaomi 13",1500],["iPhone 14",2200]]},"source":"https://www.sqlite.org/lang_select.html"},
{"id":"sql-order","version":2,"title":"Как отсортировать результат от самого дорогого товара к самому дешёвому?","context":"Все показанные цены различаются. Нужно вывести name и price для всех товаров и изменить только порядок строк.","query":"SELECT name, price\nFROM products\n/* добавь сортировку */;","choices":["ORDER BY price ASC","ORDER BY price DESC","ORDER BY name DESC"],"answer":1,"hint":"ORDER BY задаёт сортировку. Сначала выбери поле цены, затем направление: ASC — возрастание, DESC — убывание.","why":["ASC отсортирует от меньшей цены к большей. Нужен обратный порядок.","Верно: сортируем именно price и по убыванию — DESC.","Это сортировка названий, а не цен. Она не гарантирует порядок от дорогого к дешёвому."],"steps":["Сортируем price: это поле цены.","DESC — по убыванию, от большего значения к меньшему.","На этих данных получим цены: 3000, 2500, 2200, 1500."],"rule":"ORDER BY price DESC — от дорогих к дешёвым. ORDER BY price ASC — наоборот. При равных ценах для однозначного порядка понадобится дополнительное поле.","columns":["name","price","stock"],"rows":[["iPhone 15",3000,5],["Samsung S24",2500,0],["Xiaomi 13",1500,10],["iPhone 14",2200,3]],"displayOrder":[0,1,2],"verification":{"sql":"SELECT name,price FROM products ORDER BY price DESC;","columns":["name","price"],"rows":[["iPhone 15",3000],["Samsung S24",2500],["iPhone 14",2200],["Xiaomi 13",1500]]},"source":"https://www.sqlite.org/lang_select.html"}
];
